contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 tokenId0,
        uint256 tokenId1,
        uint256 points0,
        uint256 points1,
        uint256 extraPoints
    ) public {
        // Ensure distinct token IDs so winner selection cannot double-count
        require(tokenId0 != tokenId1);

        // Set the number of winners to 2 to match the array length passed below
        c.updateWinnersPerPeriod(2);

        // Read the before state of totalPoints
        uint256 beforeTotal = c.totalPoints();
        uint256 beforeRoundId = c.roundId();
        bool completeItBefore = c.isSelectionComplete(beforeRoundId);

        // Ensure the current round selection is not already complete
        require(!completeItBefore);

        // Add points to the two fighters that will be selected
        c.addPoints(tokenId0, points0);
        c.addPoints(tokenId1, points1);

        // Add extra points to some other fighter not selected to make sure pickWinner only removes selected points
        uint256 otherToken = tokenId0 + tokenId1 + extraPoints + 1;
        if (otherToken == tokenId0 || otherToken == tokenId1) {
            otherToken = otherToken + 1;
        }
        c.addPoints(otherToken, extraPoints);

        // Read the after addPoints state
        uint256 midTotal = c.totalPoints();
        uint256 points0BeforePick = c.fighterPoints(tokenId0);
        uint256 points1BeforePick = c.fighterPoints(tokenId1);
        uint256 otherPointsBeforePick = c.fighterPoints(otherToken);

        // Build the winners array and call pickWinner
        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenId0;
        winners[1] = tokenId1;

        // This call creates the state change we test
        c.pickWinner(winners);

        // Read the after state
        uint256 afterTotal = c.totalPoints();
        uint256 afterRoundId = c.roundId();
        bool completeItAfter = c.isSelectionComplete(beforeRoundId);
        uint256 points0After = c.fighterPoints(tokenId0);
        uint256 points1After = c.fighterPoints(tokenId1);
        uint256 otherPointsAfter = c.fighterPoints(otherToken);

        // Assert the general rule:
        // pickWinner must reset the selected fighters' points to zero,
        // subtract exactly their prior points from totalPoints,
        // leave other fighters' points untouched,
        // mark the round complete, and increment roundId.
        assert(
            points0After == 0 &&
            points1After == 0 &&
            otherPointsAfter == otherPointsBeforePick &&
            afterTotal == midTotal - points0BeforePick - points1BeforePick &&
            completeItAfter &&
            afterRoundId == beforeRoundId + 1
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 tokenId0,
        uint256 tokenId1,
        uint256 points0,
        uint256 points1,
        uint256 otherTokenId,
        uint256 otherPoints
    ) public {
        require(tokenId0 != tokenId1);
        require(otherTokenId != tokenId0 && otherTokenId != tokenId1);

        // Use the already existing winnersPerPeriod default of 2 by setting it explicitly.
        c.updateWinnersPerPeriod(2);

        uint256 beforeRoundId = c.roundId();
        require(!c.isSelectionComplete(beforeRoundId));

        uint256 beforeTotal = c.totalPoints();

        c.addPoints(tokenId0, points0);
        c.addPoints(tokenId1, points1);
        c.addPoints(otherTokenId, otherPoints);

        uint256 midTotal = c.totalPoints();
        uint256 points0Before = c.fighterPoints(tokenId0);
        uint256 points1Before = c.fighterPoints(tokenId1);
        uint256 otherBefore = c.fighterPoints(otherTokenId);

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenId0;
        winners[1] = tokenId1;
        c.pickWinner(winners);

        uint256 afterTotal = c.totalPoints();
        uint256 afterRoundId = c.roundId();
        bool completeAfter = c.isSelectionComplete(beforeRoundId);
        uint256 points0After = c.fighterPoints(tokenId0);
        uint256 points1After = c.fighterPoints(tokenId1);
        uint256 otherAfter = c.fighterPoints(otherTokenId);

        assert(
            points0After == 0 &&
            points1After == 0 &&
            otherAfter == otherBefore &&
            afterTotal == midTotal - points0Before - points1Before &&
            completeAfter &&
            afterRoundId == beforeRoundId + 1
        );
    }
}

