contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) public payable {
        require(modelURIs.length == customAttributes.length && modelTypes.length == customAttributes.length);
        uint32 before = c.numRoundsClaimed(address(this));
        uint256 rid = c.roundId();
        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint32 after = c.numRoundsClaimed(address(this));
        if (!reverted) {
            assert(after == rid);
        } else {
            assert(true);
        }
    }
    receive() external payable {}
}

