contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points, uint256[] calldata winners) public payable {
        require(address(this).balance >= 0);
        require(winners.length == c.winnersPerPeriod());

        c.addPoints(tokenId, points);

        uint256 beforePoints = c.fighterPoints(tokenId);

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterPoints = c.fighterPoints(tokenId);
            bool isWinner = false;
            for (uint256 i = 0; i < winners.length; i++) {
                if (winners[i] == tokenId) {
                    isWinner = true;
                    break;
                }
            }
            if (isWinner) {
                assert(afterPoints == 0 || beforePoints == afterPoints);
            }
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points, uint256[] calldata winners) public payable {
        require(winners.length == c.winnersPerPeriod());

        c.addPoints(tokenId, points);

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool contained = false;
        for (uint256 i = 0; i < winners.length; i++) {
            if (winners[i] == tokenId) {
