contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address adminAddress, bool access) public {
        // Only the owner can call adjustAdminAccess, and this test contract deployed c,
        // so it is the owner if caller == address(this).
        bool callerIsOwner = (caller == address(this));

        // Read the admin flag before the call using the public getter.
        bool before = c.isAdmin(adminAddress);

        // Make the deciding top-level call, using caller as msg.sender is not possible
        // (msg.sender is this contract), so the only owner in this fresh deployment is
        // address(this). We therefore test the behavior for owner vs. non-owner by
        // requiring a precondition when needed.
        require(callerIsOwner, "test only drives owner path");

        bool reverted;
        try c.adjustAdminAccess(adminAddress, access) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: when the owner calls adjustAdminAccess, it must not revert,
        // and afterwards the public isAdmin flag for the target must equal the
        // requested access value.
        if (!reverted) {
            assert(c.isAdmin(adminAddress) == access);
        } else {
            assert(before == c.isAdmin(adminAddress));
        }
    }

    receive() external payable {}
}

