                address entry = c.winnerAddresses(r, j);
                if (entry == claimer) {
                    seenMatches += 1;
                }
            }
        }

        assert(unclaimed <= roundsToCheck);
        assert(seenMatches <= unclaimed);
    }

    receive() external payable {}
}

