        require(secondCaller != address(0));
        require(newOwner != secondCaller);

        // This contract (msg.sender == address(this)) is the initial owner of c.
        c.transferOwnership(newOwner);

        // Reaching here proves that an owner caller was not reverted by transferOwnership.
        // If transferOwnership had wrong ownership logic and reverted, this call would propagate the revert.

