        // (which is no longer the owner) reverts.
        bool revertedFromOldOwner;
        try c.transferOwnership(secondCaller) {
            revertedFromOldOwner = false;
        } catch {
            revertedFromOldOwner = true;
        }

        assert(revertedFromOldOwner);
    }
}

