contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rankedBattleAddress, address ownerAddress, uint256 tokenId, uint256 points) public {
        // Fresh deployment: totalPoints starts at 0 and fighterPoints[tokenId] starts at 0.
        // The only address allowed to call addPoints is the RankedBattle address.
        // We cannot impersonate the RankedBattle address directly from the test contract
        // other than by the fact that the test contract is a fresh deployer. However,
        // the constructor of c was called with msg.sender == address(this), and addPoints
        // requires msg.sender == _rankedBattleAddress. We therefore create two scenarios:
        // (1) an arbitrary caller (address(this)) that is not the RankedBattle address must revert,
        // (2) only if address(this) happens to equal the RankedBattle address would it succeed.
        // We can force the successful path to be reachable by checking the precondition that
        // msg.sender (which is this contract) equals the RankedBattle address passed in.
        // But since we cannot change msg.sender, we instead assert the general rule that
        // addPoints either reverts (wrong caller) or, when allowed, strictly increases both
        // fighterPoints[tokenId] and totalPoints by points, and that the two increments are equal.

        uint256 pointsBefore = c.fighterPoints(tokenId);
        uint256 totalBefore = c.totalPoints();

        bool reverted;
        try c.addPoints(tokenId, points) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 pointsAfter = c.fighterPoints(tokenId);
        uint256 totalAfter = c.totalPoints();

        // General rule: addPoints reverts exactly when the caller is not the RankedBattle address.
        // Since the test contract is the caller and was also the deployer, we can only be the
        // RankedBattle address if the constructor was given address(this). However, we cannot
        // know that address here. So we state the observable invariant: on success the two
        // point counters must increase by exactly points; on revert neither counter changes.
        // This distinguishes a faulty implementation that updates only one counter or uses
        // a wrong amount.
        assert(
            (reverted && pointsAfter == pointsBefore && totalAfter == totalBefore) ||
            (!reverted && pointsAfter == pointsBefore + points && totalAfter == totalBefore + points)
        );
    }
}

