    function run(uint256 r, uint256 w) public payable {
        require(r < 1000, "round too large");
        uint256 beforeRound = c.roundId();
        require(beforeRound <= r, "r must be current or future round");
        bool reverted;
        uint256[] memory winners = new uint256[](1);
        winners[0] = w;
        try c.pickWinner(winners) { reverted = false; } catch { reverted = true; }
        uint256 afterRound = c.roundId();
        bool sel = c.isSelectionComplete(r);
        assert(sel == true || afterRound == beforeRound || reverted);
    }

    receive() external payable {}
}

