contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address originalOwner = c._ownerAddress();
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            assert(c._ownerAddress() == newOwner);
            assert(c.isAdmin(newOwner));
        } else {
            assert(c._ownerAddress() == originalOwner);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address secondOwner) public {
        bool firstReverted;
        try c.transferOwnership(newOwner) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        assert(!firstReverted);
        assert(c.isAdmin(newOwner) == (newOwner != address(0)) || newOwner == address(0));

        bool secondReverted;
        try c.transferOwnership(secondOwner) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(secondReverted || secondOwner == newOwner);
    }

    receive() external payable {}
}
